create policy occupancies_v2_self_read on public.occupancies_v2 for select to authenticated using (user_id = (select auth.uid())); create policy occupancies_v2_admin_read on public.occupancies_v2 for select to authenticated using ((select auth.jwt()->'app_metadata'->>'role') = 'root' or ((select auth.jwt()->'app_metadata'->>'role') = 'admin' and organization_id::text = (select auth.jwt()->'app_metadata'->>'organization_id')));
